import { useEffect, useState } from "react";
import { callAPI } from "../../../utils/apiUtils";
import { apiUrls } from "../../../utils/apiUrls";
import { SelectBoxLoader } from "../../../helpers/common";

function GetAllForedit({
    values = [],
    fn,
    load,
    name = "optionTypeId",
    disabled = false,
    className = null,
    producttypeId = "",
    indexId = 0,
}) {
    const [optionList, setOptionList] = useState([]);
    const [allOption, setAllOption] = useState([]);
    const [show, setShow] = useState(false);

    const fetchOptions = async () => {
        try {
            if (!producttypeId) return;
            setShow(true);

            const query = { ProductTypeId: producttypeId };
            const apiResponse = await callAPI(apiUrls.GetAllOption, query, "GET", {});
            setShow(false);

            if (apiResponse?.data?.isSuccess) {
                const fetchedOptions = apiResponse?.data?.data || [];
                setOptionList(fetchedOptions);

                const defaultOptions = fetchedOptions.reduce((acc, item) => {
                    const selectedOptions = item?.options?.filter((option) =>
                        values.length > 0
                            ? values.includes(option?.optionTypeId?.toUpperCase())
                            : option.isDefault
                    );

                    const mappedOptions = selectedOptions?.map((option) => ({
                        optionName: `${item?.optionId}-${indexId}`,
                        value: option?.optionTypeId,
                    }));

                    return [...acc, ...mappedOptions];
                }, []);

                setAllOption(defaultOptions);
            } else {
                setOptionList([]);
                setAllOption([]);
            }
        } catch (error) {
            setShow(false);
            setOptionList([]);
            setAllOption([]);
        }
    };

    useEffect(() => {
        if ( allOption.length > 0) {
            fn({ target: { name, value: allOption.map((obj) => obj.value) } });
        }
        // eslint-disable-next-line 
    }, [allOption]); // Keep only the necessary dependency
    

    useEffect(() => {
        if (producttypeId) {
            fetchOptions();
        }
        // eslint-disable-next-line 
    }, [producttypeId, load]); // Removed `values` from dependency
    

    const handleChangeOption = (e, optionName, optionTypeId) => {
        const updatedOption = {
            optionName: `${optionName}-${indexId}`,
            value: optionTypeId,
        };

        setAllOption((prevOptions) => {
            const existingIndex = prevOptions.findIndex(
                (opt) => opt.optionName === updatedOption.optionName
            );

            if (existingIndex !== -1) {
                const newOptions = [...prevOptions];
                newOptions[existingIndex] = updatedOption;
                return newOptions;
            } else {
                return [...prevOptions, updatedOption];
            }
        });
    };

    return (
        <div className="position-relative">
            {show && <SelectBoxLoader />}
            <div>
                {optionList.map((item, i) => (
                    <div key={i} className="d-flex gap-3">
                        <label className="form-check-label font-14 bold-label" htmlFor={`flexCheck-${item?.optionId}`}>
                            {item?.optionName}
                        </label>
                        <div className="d-flex gap-2 flex-wrap">
                            {item?.options.map((option, index) => (
                                <div className="form-check" key={index}>
                                    <input
                                        className="form-check-input"
                                        type="radio"
                                        id={`flexCheck-${option?.optionTypeId}-${indexId}`}
                                        name={`${item?.optionId}-${indexId}`}
                                        value={option?.optionTypeId}
                                        checked={
                                            allOption.some(
                                                (opt) =>
                                                    opt.optionName === `${item?.optionId}-${indexId}` &&
                                                    opt.value === option?.optionTypeId
                                            ) ||
                                            values.some(
                                                (val) =>
                                                    val?.toLowerCase() ===
                                                    option?.optionTypeId?.toLowerCase()
                                            )
                                        }
                                        onChange={(e) =>
                                            handleChangeOption(e, item?.optionId, option?.optionTypeId)
                                        }
                                        disabled={disabled}
                                    />
                                    <label
                                        className="form-check-label"
                                        htmlFor={`flexCheck-${option?.optionTypeId}-${indexId}`}
                                    >
                                        {option?.optionType}
                                    </label>
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

export default GetAllForedit;
